package com.mahesh.empleave.employee;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.mahesh.empleave.audit.*;import com.mahesh.empleave.department.*;import com.mahesh.empleave.user.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.data.domain.*;import org.springframework.security.authentication.*;import org.springframework.security.crypto.password.*;import org.springframework.test.util.*;
class EmployeeControllerTest {
 @Test void updateSavesManagerAndReturnsUpdatedFields(){var users=mock(UserRepository.class);var departments=mock(DepartmentRepository.class);var audit=mock(AuditService.class);var controller=new EmployeeController(users,departments,mock(PasswordEncoder.class),audit);var employee=user(2L,"employee@example.com",Role.EMPLOYEE,"Old");var manager=user(5L,"manager@example.com",Role.MANAGER,"Manager");var admin=user(1L,"admin@example.com",Role.ADMIN,"Admin");var department=new Department("Engineering","ENG");ReflectionTestUtils.setField(department,"id",9L);when(users.findById(2L)).thenReturn(Optional.of(employee));when(users.findById(5L)).thenReturn(Optional.of(manager));when(departments.findById(9L)).thenReturn(Optional.of(department));when(users.save(employee)).thenReturn(employee);when(users.findByEmail(admin.getEmail())).thenReturn(Optional.of(admin));var result=controller.update(new UsernamePasswordAuthenticationToken(admin.getEmail(),null),2L,new EmployeeController.Update("Updated",9L,5L));assertEquals(5L,result.managerId());assertEquals(9L,result.departmentId());assertEquals("Updated",result.fullName());verify(users).save(employee);verify(audit).log(admin,"EMPLOYEE_UPDATED","EMPLOYEE",2L);}
 @Test void updateRejectsNonManagerWithoutSaving(){var users=mock(UserRepository.class);var controller=new EmployeeController(users,mock(DepartmentRepository.class),mock(PasswordEncoder.class),mock(AuditService.class));var employee=user(2L,"employee@example.com",Role.EMPLOYEE,"Employee");when(users.findById(2L)).thenReturn(Optional.of(employee));when(users.findById(5L)).thenReturn(Optional.of(user(5L,"other@example.com",Role.EMPLOYEE,"Other")));assertThrows(IllegalArgumentException.class,()->controller.update(new UsernamePasswordAuthenticationToken("admin@example.com",null),2L,new EmployeeController.Update("Employee",null,5L)));verify(users,never()).save(employee);}
 @Test void listUsesRoleQueryForAccuratePagination(){var users=mock(UserRepository.class);var controller=new EmployeeController(users,mock(DepartmentRepository.class),mock(PasswordEncoder.class),mock(AuditService.class));var manager=user(5L,"manager@example.com",Role.MANAGER,"Manager");when(users.findByRole(eq(Role.MANAGER),any(Pageable.class))).thenReturn(new PageImpl<>(List.of(manager),PageRequest.of(1,10),11));var result=controller.list(1,10,Role.MANAGER);assertEquals(11,result.getTotalElements());assertEquals(List.of(5L),result.getContent().stream().map(x->x.id()).toList());verify(users).findByRole(eq(Role.MANAGER),any(Pageable.class));verify(users,never()).findAll(any(Pageable.class));}
 private AppUser user(Long id,String email,Role role,String name){var user=new AppUser(email,"hash",role,name);ReflectionTestUtils.setField(user,"id",id);return user;}
}
